.pks1-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.pks1-root,.pks1-root *,.pks1-root *::before,.pks1-root *::after{box-sizing:border-box}
.pks1-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.pks1-root img{display:block;border:0;max-width:none}
.pks1-root [hidden]{display:none!important}
.pks1-root .n15_8971{align-content:stretch;display:flex;flex-direction:column;height:22px;align-items:center;justify-content:center;padding-left:10px;padding-right:10px;position:relative;border-radius:100px;flex-shrink:0;border-style:solid;border-color:var(--wa-line, #343639);border-width:1.5px}
.pks1-root .x5{position:absolute;left:-1.5px;top:-1.5px;width:calc(100% + 3px);height:calc(100% + 3px);pointer-events:none;border-radius:100px}
.pks1-root .x6{position:absolute;background-color:color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 10%, transparent);inset:0;border-radius:100px}
.pks1-root .x7{position:absolute;inset:0;mix-blend-mode:overlay;border-radius:100px;background-image:linear-gradient(-29.14837710045427deg, color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 0%, transparent) 18.054%, color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 0%, transparent) 50.097%, color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 50%, transparent) 50.86%, color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 50%, transparent) 94.347%)}
.pks1-root .n15_8972{align-content:stretch;display:flex;gap:7px;align-items:center;position:relative;flex-shrink:0}
.pks1-root .n8_9195{position:relative;flex-shrink:0;width:12px;height:12px}
.pks1-root .n8_9191{position:absolute;left:0;width:12px;height:12px;top:0}
.pks1-root .x8{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.pks1-root .n15_8974{text-box-edge:cap alphabetic;text-box-trim:trim-both;word-break:break-word;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:600;line-height:1;font-style:normal;position:relative;flex-shrink:0;font-size:12px;color:var(--wa-text, #fff);white-space:nowrap;width:27px;height:8px}
.pks1-root[data-theme="light"]{background:var(--wa-bg, #eef2f7);color:var(--wa-text, #0e1a2b)}
.pks1-root[data-theme="light"] [data-name="Background"] > img{filter:invert(1) hue-rotate(180deg) saturate(0.4) brightness(1.05);opacity:0.5}
.pks1-root[data-theme="light"] [data-name="Building Image"] img{filter:saturate(0.92) brightness(0.98)}
.pks1-root[data-theme="light"] [data-name="Floor Plan"] img{filter:invert(1) hue-rotate(180deg) saturate(0.55) brightness(1.04)}
.pks1-root[data-theme="light"] [data-name^="Popup/"] > [data-name="Background"]::after{content:"";position:absolute;inset:0;border-radius:inherit;background:color-mix(in srgb, var(--wa-bg, rgb(247 250 254)) 92%, transparent);pointer-events:none}
.pks1-root[data-theme="light"] .n15_8971{border-color:var(--wa-line, #d0d2d6)}
.pks1-root[data-theme="light"] .x6{background-color:color-mix(in srgb, var(--wa-bg, rgb(0 45 36)) 6%, transparent)}
.pks1-root[data-theme="light"] .x7{background-image:linear-gradient(-29.14837710045427deg, color-mix(in srgb, var(--wa-surface, rgb(90 95 104)) 0%, transparent) 18.054%, color-mix(in srgb, var(--wa-surface, rgb(90 95 104)) 0%, transparent) 50.097%, color-mix(in srgb, var(--wa-surface, rgb(90 95 104)) 50%, transparent) 50.86%, color-mix(in srgb, var(--wa-surface, rgb(90 95 104)) 50%, transparent) 94.347%)}
.pks1-root[data-theme="light"] .n15_8974{color:var(--wa-text, #10231d)}
